+import { ReactElement, createRef } from 'react';
+
+import { act, renderHook } from '@testing-library/react-hooks';
+
+import { useLinkHandler } from './useLinkHandler';
+
+const mockCreateNotification = jest.fn();
+const mockSetModalOpen = jest.fn();
+
+jest.mock('./index', () => ({
+    useHandler: (handler: unknown) => handler,
+    useNotifications: () => ({ createNotification: mockCreateNotification }),
+}));
+
+jest.mock('../components', () => ({
+    useModalState: () => [{ open: false }, mockSetModalOpen],
+}));
+
+jest.mock('../components/notifications/LinkConfirmationModal', () => () => null);
+
+describe('useLinkHandler', () => {
+    beforeEach(() => {
+        mockCreateNotification.mockClear();
+        mockSetModalOpen.mockClear();
+    });
+
+    it('shows the punycode URL in the confirmation modal', () => {
+        const wrapper = document.createElement('div');
+        const anchor = document.createElement('a');
+        anchor.setAttribute('href', 'https://www.аррӏе.com/path/?q=1#part');
+        wrapper.appendChild(anchor);
+        const wrapperRef = createRef<HTMLDivElement>();
+        Object.defineProperty(wrapperRef, 'current', { value: wrapper });
+
+        const { result } = renderHook(() => useLinkHandler(wrapperRef));
+        act(() => {
+            anchor.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true }));
+        });
+
+        expect((result.current.modal as ReactElement<{ link: string }>).props.link).toBe(
+            'https://www.xn--80ak6aa92e.com/path?q=1#part'
+        );
+        expect(mockSetModalOpen).toHaveBeenCalledWith(true);
+    });
+
+    it('shows an error for an anchor without a URL', () => {
+        const wrapper = document.createElement('div');
+        const anchor = document.createElement('a');
+        wrapper.appendChild(anchor);
+        const wrapperRef = createRef<HTMLDivElement>();
+        Object.defineProperty(wrapperRef, 'current', { value: wrapper });
+
+        renderHook(() => useLinkHandler(wrapperRef));
+        const event = new MouseEvent('click', { bubbles: true, cancelable: true });
+        act(() => {
+            anchor.dispatchEvent(event);
+        });
+
+        expect(event.defaultPrevented).toBe(true);
+        expect(mockCreateNotification).toHaveBeenCalledWith(expect.objectContaining({ type: 'error' }));
+    });
+});
